import {
  cloneElement,
  createContext,
  isValidElement,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faHouse } from '@fortawesome/free-solid-svg-icons';
import { useLocation, useNavigate } from 'react-router-dom';
import OptionsModal from '../optionsModal/optionsModal';
import './appShell.scss';

const AppShellContext = createContext({ isOptionsOpen: false });
const PAGE_TRANSITION_DURATION_MS = 250;

export function useAppShell() {
  return useContext(AppShellContext);
}

function AppShell({ children }) {
  const location = useLocation();
  const navigate = useNavigate();
  const [isOptionsOpen, setIsOptionsOpen] = useState(false);
  const [displayLocation, setDisplayLocation] = useState(location);
  const [transitionPhase, setTransitionPhase] = useState('idle');
  const displayedLocationRef = useRef(location);
  const pageTransitionRef = useRef(null);
  const exitTimerRef = useRef(null);
  const enterTimerRef = useRef(null);
  const contextValue = useMemo(() => ({ isOptionsOpen }), [isOptionsOpen]);
  const usesLetsSpellTheme =
    displayLocation.pathname === '/letsSpell' ||
    displayLocation.pathname.startsWith('/letsSpell/');
  const usesLetsFindTheme =
    displayLocation.pathname === '/letsFind' ||
    displayLocation.pathname.startsWith('/letsFind/');
  const displayedChildren = isValidElement(children)
    ? cloneElement(children, { location: displayLocation })
    : children;

  const goHome = () => {
    if (location.pathname !== '/') {
      navigate('/');
    }
  };

  useEffect(() => {
    if (location.key === displayedLocationRef.current.key) {
      return undefined;
    }

    window.clearTimeout(exitTimerRef.current);
    window.clearTimeout(enterTimerRef.current);

    const activeElement = document.activeElement;

    if (pageTransitionRef.current?.contains(activeElement)) {
      activeElement.blur();
    }

    const showLocation = (nextLocation) => {
      displayedLocationRef.current = nextLocation;
      setDisplayLocation(nextLocation);
    };
    const focusIncomingPage = () => {
      if (document.activeElement === document.body) {
        pageTransitionRef.current
          ?.querySelector(
            '[data-directional-navigation-item]:not(:disabled):not([aria-disabled="true"])',
          )
          ?.focus({ preventScroll: true });
      }
    };
    const prefersReducedMotion =
      window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;

    if (prefersReducedMotion) {
      showLocation(location);
      setTransitionPhase('idle');
      enterTimerRef.current = window.setTimeout(focusIncomingPage, 0);
    } else {
      setTransitionPhase('exiting');
      exitTimerRef.current = window.setTimeout(() => {
        showLocation(location);
        setTransitionPhase('entering');
        enterTimerRef.current = window.setTimeout(() => {
          setTransitionPhase('idle');
          focusIncomingPage();
        }, PAGE_TRANSITION_DURATION_MS);
      }, PAGE_TRANSITION_DURATION_MS);
    }

    return () => {
      window.clearTimeout(exitTimerRef.current);
      window.clearTimeout(enterTimerRef.current);
    };
  }, [location]);

  useLayoutEffect(() => {
    const letsSpellThemeClass = 'theme--lets-spell';
    const letsFindThemeClass = 'theme--lets-find';

    document.documentElement.classList.toggle(letsSpellThemeClass, usesLetsSpellTheme);
    document.documentElement.classList.toggle(letsFindThemeClass, usesLetsFindTheme);

    return () => {
      document.documentElement.classList.remove(letsSpellThemeClass, letsFindThemeClass);
    };
  }, [usesLetsFindTheme, usesLetsSpellTheme]);

  return (
    <AppShellContext.Provider value={contextValue}>
      <div className="app-shell">
        <div
          ref={pageTransitionRef}
          aria-hidden={transitionPhase === 'exiting' ? 'true' : undefined}
          className={`app-shell__page-transition app-shell__page-transition--${transitionPhase}`}
          inert={transitionPhase === 'exiting'}
        >
          {displayedChildren}
        </div>
        <button
          className="app-shell__menu"
          aria-label="Go to Home"
          disabled={transitionPhase !== 'idle'}
          onClick={goHome}
          type="button"
        >
          <FontAwesomeIcon icon={faHouse} />
        </button>
        <OptionsModal
          isOpen={isOptionsOpen}
          onClose={() => setIsOptionsOpen(false)}
        />
      </div>
    </AppShellContext.Provider>
  );
}

export default AppShell;
